function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10 * Math.sin(t));
  ctx.lineTo(W/2, H/2 + 50 + 10 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 10 * Math.sin(t));
  ctx.lineTo(W/2 - 20 + 10 * Math.cos(t), H/2 + 70 + 10 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 10 * Math.sin(t));
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(t), H/2 + 70 + 10 * Math.sin(t));
  ctx.stroke();

  // draw changing background shapes
  ctx.fillStyle = 'black';
  ctx.globalAlpha = 0.2;
  ctx.beginPath();
  ctx.arc(W/2 + 50 * Math.cos(t), H/2 + 50 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 70 * Math.cos(t + Math.PI/2), H/2 + 70 * Math.sin(t + Math.PI/2), 30, 0, 2 * Math.PI);
  ctx.fill();

  ctx.globalAlpha = 1;
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('everything changes', W/2, H/2 - 80 + 10 * Math.sin(t));
  ctx.fillText('always', W/2, H/2 - 50 + 10 * Math.sin(t));

  ctx.restore();
}
